import {spots,finite,angle,conditions,assess} from './model.js';
const $=id=>document.getElementById(id),fmt=t=>new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',weekday:'short',month:'short',day:'numeric',hour:'numeric',minute:'2-digit'}).format(t*1000),num=(v,suffix='',digits=1)=>finite(v)?v.toFixed(digits)+suffix:'Unavailable';
const feet=v=>finite(v)?v*3.28084:null;
let selected=0,time=null,loading=true,records={},errors={},generation=0;
async function json(url){const r=await fetch(url,{signal:AbortSignal.timeout(20000)});if(!r.ok)throw Error('HTTP '+r.status);const d=await r.json();if(d.error)throw Error('Provider error');return d;}
async function load(force=false){const run=++generation;loading=true;errors={};$('refresh').disabled=true;render();await Promise.all(spots.map(async s=>{try{let cached;try{cached=JSON.parse(sessionStorage.getItem('lineup-v3-'+s.id))}catch{}if(!force&&cached&&Date.now()-cached.fetched<15*60e3){records[s.id]=cached;return;}
const coords=new URLSearchParams({latitude:s.lat,longitude:s.lon,forecast_days:3,timeformat:'unixtime',timezone:'GMT'});
const tideParams=new URLSearchParams({begin_date:new Date().toISOString().slice(0,10).replaceAll('-',''),end_date:new Date(Date.now()+3*86400e3).toISOString().slice(0,10).replaceAll('-',''),station:s.station,product:'predictions',datum:'MLLW',time_zone:'gmt',interval:'h',units:'metric',format:'json'});
const values=await Promise.allSettled([json('https://marine-api.open-meteo.com/v1/marine?'+coords+'&hourly=wave_height,swell_wave_height,swell_wave_period,swell_wave_direction'),json('https://api.open-meteo.com/v1/forecast?'+coords+'&hourly=wind_speed_10m,wind_direction_10m,is_day&wind_speed_unit=kn'),json('https://api.tidesandcurrents.noaa.gov/api/prod/datagetter?'+tideParams)]);
if(run!==generation)return;const [m,w,t]=values.map(v=>v.status==='fulfilled'?v.value:null);const tides=t?.predictions?.map(p=>({time:Date.parse(p.t.replace(' ','T')+'Z')/1000,value:Number(p.v)}));const data={marine:m,weather:w,tides,fetched:Date.now()};records[s.id]=data;if(!m||!w||!tides)errors[s.id]='One or more providers could not be reached. Try refresh.';else try{sessionStorage.setItem('lineup-v3-'+s.id,JSON.stringify(data))}catch{}
}catch{records[s.id]=null;errors[s.id]='Forecast request failed. Try refresh.'}}));if(run!==generation)return;loading=false;setHours();$('refresh').disabled=false;render();}
function setHours(){const now=Date.now()/1000;const times=[...new Set(Object.values(records).flatMap(r=>r?.marine?.hourly?.time||[]))].filter(t=>t>=Math.floor(now/3600)*3600&&t<=now+48*3600).sort((a,b)=>a-b);if(!times.includes(time))time=times.find(t=>spots.some(s=>conditions(records[s.id],t)?.day===1))??times[0]??null;$('hour').innerHTML=times.length?times.map(t=>`<option value="${t}">${fmt(t)} PT</option>`).join(''):'<option>No forecast hours available</option>';$('hour').disabled=!times.length;$('hour').value=time;}
function boardAdvice(s,c,a){if(a.rank<=0)return ['Conditions come before equipment.','A different board cannot resolve the conditions or missing information behind this call.'];const b=$('board').value,l=$('level').value;if(l==='beginner')return ['Prioritize stability and instruction.','A suitable foam board and a local instructor are a better starting point than a short fish. Practice in manageable whitewater after an on-site check.'];if(b==='fish')return ['Your 5′10″ fish could fit open faces.','A wide, low-rocker fish can carry speed on smaller peeling waves. That depends on the actual face shape; offshore data cannot tell us whether this bank is hollow or closing out.'];if(b==='foam')return ['Your 8′ foam board favors glide.','Length and volume help with early entry on soft waves. Tight, steep pockets and crowded lineups demand control; foam construction alone does not determine suitability.'];return ['Your shortboard needs usable push.','At 29 L for this 75 kg example rider, paddle fitness and wave-catching ability matter. Check whether the actual faces offer enough speed.'];}
function render(){const level=$('level').value,b=$('board').value;const cs=spots.map(s=>conditions(records[s.id],time));const as=spots.map((s,i)=>assess(s,cs[i],level,b));const best=as.reduce((n,a,i)=>a.rank>as[n].rank?i:n,0),pick=as[best].rank>0;
$('skillHint').textContent={beginner:'Learning takeoffs and board control.',intermediate:'Catching green waves and turning both ways.',advanced:'Strong board control and confident takeoffs.'}[level];$('heroPill').textContent=loading?'UPDATING FORECASTS':pick?'LOCAL FORECAST · PERSONAL FIT':'NO SESSION PICK';$('heroTitle').textContent=loading?'Reading the SoCal coast…':pick?`Take a closer look at ${spots[best].name}.`:'A good day to check before you go.';$('heroCopy').textContent=loading?'Fetching swell, wind and tide predictions for three real surf spots.':pick?as[best].reasons[0]:'No spot passes the current screen, or required data is unavailable. Choose another hour or refresh the forecast.';$('heroSpot').textContent=loading?'Fetching…':pick?spots[best].region:'Check locally';$('heroTime').textContent=time?new Intl.DateTimeFormat('en-US',{timeZone:'America/Los_Angeles',hour:'numeric',minute:'2-digit'}).format(time*1000):'—';$('explain').disabled=loading||!pick;$('explain').onclick=()=>{selected=best;render();$('details').scrollIntoView({behavior:'smooth'})};
$('cards').innerHTML=spots.map((s,i)=>`<button class="spot ${selected===i?'active':''}" data-spot="${i}" aria-pressed="${selected===i}"><div class="spot-top"><span>${s.region.toUpperCase()}</span><span>${num(feet(cs[i]?.height),' ft')} Hs</span></div><h4>${s.name}</h4><p>${s.type}</p><span class="status ${as[i].rank<=0?'avoid':as[i].rank===1?'caution':''}">${loading?'Loading…':as[i].title}</span></button>`).join('');document.querySelectorAll('[data-spot]').forEach(x=>x.onclick=()=>{selected=+x.dataset.spot;render()});
const s=spots[selected],c=cs[selected],a=as[selected],d=records[s.id],adv=boardAdvice(s,c,a),windLabel=c&&finite(c.windDirection)?angle(c.windDirection,s.normal)<60?'Onshore':angle(c.windDirection,s.normal)>120?'Offshore':'Cross-shore':'Unknown';
$('details').innerHTML=`<div class="detail-head"><h3>${s.name}, decoded.</h3><span>${time?fmt(time)+' PT':'Awaiting forecast'}</span></div><div class="metrics"><div><small>Offshore total Hs</small><strong>${num(feet(c?.height),' ft')}</strong></div><div><small>Main swell · mean period</small><strong>${num(feet(c?.swell),' ft')} / ${num(c?.period,' s')}</strong></div><div><small>Swell from</small><strong>${num(c?.direction,'°',0)}</strong></div><div><small>Wind · ${windLabel}</small><strong>${num(c?.wind,' kn')} / ${num(c?.windDirection,'°',0)}</strong></div></div><p class="data-caption">Hs is modeled significant wave height at an offshore grid cell, not the height of breaking surf. Local face height is uncalibrated.</p><div class="reasons"><div class="reason"><span class="reason-num">01 / YOUR CONDITIONS</span><h4>${loading?'Forecast loading':a.title}</h4>${a.reasons.map(r=>`<p>• ${r}</p>`).join('')}</div><div class="reason"><span class="reason-num">02 / THE LOCAL BREAK</span><h4>${s.type}</h4><p>${s.note}</p><p style="margin-top:10px">Tide: <strong>${num(feet(c?.tide),' ft MLLW')}</strong> at ${s.stationName}. A nearby reference prediction, not water depth over the break.</p></div></div><div class="board"><div class="board-icon">◒</div><div><h4>${adv[0]}</h4><p>${adv[1]}</p></div></div><div class="note">${errors[s.id]||'Water quality, active warnings, crowding and real-time rip currents are not checked automatically.'} <a href="${s.water}" target="_blank" rel="noopener">Check water quality ↗</a> · <a href="${s.source}" target="_blank" rel="noopener">Official beach information ↗</a> · <a href="https://tidesandcurrents.noaa.gov/noaatidepredictions.html?id=${s.station}" target="_blank" rel="noopener">NOAA tides ↗</a></div><div class="data-caption">${d?'Retrieved '+fmt(d.fetched/1000)+' PT.':'No live data yet.'} ${d?.marine?'Marine grid: '+d.marine.latitude.toFixed(3)+', '+d.marine.longitude.toFixed(3)+'.':''} Spot coordinates and shoreline orientation are approximate. Surf-zone confidence: limited.</div>`;
$('liveStatus').textContent=loading?'Fetching live forecasts…':Object.keys(errors).length?'Some feeds unavailable · refresh to retry':'Live model feeds connected · refreshes every 15 min';}
$('level').onchange=render;$('board').onchange=render;$('hour').onchange=()=>{time=Number($('hour').value);render()};$('refresh').onclick=()=>load(true);setInterval(()=>load(),15*60e3);document.addEventListener('visibilitychange',()=>{if(!document.hidden)load()});load();
